custom_css:
/* 本美化免费发布于社区尾巴镇，不准倒卖二传等一切商业化行为！ */

/* 部分代码源@旅程美化教程贴的老师们 */

/* 素材鸣谢🍠小灵光 槿凉 */

@import url("https://fontsapi.zeoseven.com/309/main/result.css");

body {
    font-family: "KingHwaOldSong";
    font-weight: normal;
    /* font-feature-settings: "hwid"; 启用等宽变化字形 */
}

/*菜单背景 */
.drawer-content {
    background-image: url('无');
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
}

/*气泡本体 */
.mes {
  background: none;
  background-image: url('https://i.postimg.cc/VLH9MyYz/IMG-2776.png');
  background-position: center center;
  background-repeat: repeat-y;
  background-size: 100%;
  background-attachment: scroll;
  box-shadow: 0 0 0px rgba(238, 151, 169, 0.8);
}

.mes {  
    --vertical-spacing: 3rem; 
     margin: var(--vertical-spacing) auto !important;
  --bubble-width: 100%;
}

/* ai文本 */
.mes[is_user="false"] .mes_text {
    padding: 130px 1px 50px 1px !important;
    letter-spacing: -0.3px;
}

/* 用户文本 */
.mes[is_user="true"] .mes_text {
    padding: 145px 8px 50px 8px !important; 
    letter-spacing: -0.3px;
}
.mes_text {
    line-height: 1.9; 
margin-left: -5px !important;
font-weight: 500!important;
    filter: 
    drop-shadow(0 -1px 0.5px rgba(0, 0, 0, 0.1))
    drop-shadow(1px 1.5px 0 rgba(255, 255, 255, 1));
}

/*底层图片🫐 */
.mes::after {
  content: "";
  display: inline-block;
  background-image: url('https://i.postimg.cc/X7TG4njN/IMG-2777.png');
  background-size: contain; 
  background-repeat: no-repeat;
  background-position: center center; 

  width: 358px; /*宽度🫐没反应的话先调高 高度，再动宽度 */
  height: 90px; /*高度🫐 */

  /* 调整位置*/
  position: absolute;
  bottom: -15px; /*上下🫐 */
  left: 50%; /*左右🫐 */
  transform: translateX(-50%); /* 水平居中修正 */
}

/*顶层贴图🫐 */
.mes::before {
  content: "";
  display: inline-block;
  background-image: url('https://i.postimg.cc/d0C9wWPn/IMG-2775.png');
  background-size: contain; 
  background-repeat: no-repeat;
  background-position: center center; 

  /* 调整大小 */
  width: 358px; /*宽度🫐没反应的话先调高 高度，再动宽度 */
  height: 220px; /*高度🫐 */

  /* 调整位置 */
  position: absolute;
  top: -64px; /*上下🫐 */
  left: 50%; /*左右🫐 */
  transform: translateX(-50%); /* 水平居中修正 */
}
.swipes-counter {
  position: absolute;
  top: -1px;
  right: 90px;
  z-index: 999;
  pointer-events: none;
}
.swipes-counter {
  font-size: 9px;
  opacity: 1 !important;
  color: rgba(137, 152, 155, 0.5) !important;
  white-space: nowrap !important;
}
/*滑块图标 */
input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
    appearance: none;
    width: 29px;
    height: 29px;
    top: 0px;
    background: transparent url('https://iili.io/fhcNDj2.md.png') center/cover no-repeat;
    border: none;
    border-radius: 0;
    box-shadow: none;
    cursor: ew-resize;
    position: relative;
    z-index: 1;
}

input[type="range"] {
    background: #c6d071 !important;
    box-shadow: 0px 3px 3px rgba(161, 177, 181, 0.6)!important; 
    padding: 2px 1px 0px 1px !important;
    height: 0px; 
}

input:not([type="file" i], 
[type="image" i], 
[type="checkbox" i], 
[type="radio" i]) {
  background: #f0efed !important;  
  border-radius: 0px !important; 
  box-shadow: 
  inset 0px 0px 0px rgba(230, 239, 182, 0.9),
  0px 4px 3px rgba(161, 177, 181, 0.6);
  border: 0.9px solid #a1b1b5 !important;
outline: 1px solid #f0efed !important; 
padding: 2px 1px 0px 1px !important;
  color: #7F8D93;
  outline: none;
margin: 6px;
}

/*拓展键 */
.fa-bars {
  background: url('https://iili.io/fh7bzuI.md.png') center/contain no-repeat !important;
  width: 20px !important;
  height: 20px !important;
  margin-top: 2px !important;
  opacity: 1 !important
}

/*菜单键 */
#extensionsMenuButton {
  background: url('https://iili.io/fh7bzuI.md.png') center/contain no-repeat !important;
  width: 20px !important;
  height: 20px !important;
  margin-top: 2px !important;
opacity: 1 !important
}

/* 发送键 */
.fa-paper-plane {
  background: url('https://iili.io/fh7bzuI.md.png') center/contain no-repeat !important;
  width: 20px !important;
  height: 20px !important;
  margin-top: 2px !important;
  opacity: 1 !important
}

/* 暂停键 */
.fa-circle-stop::before {
  color: #f7f6f4;
  font-size: 1em;
  opacity: 1 !important;
}

/* 输入框 */
#send_form {
  background: url('https://i.postimg.cc/TYg6ZxhS/IMG-2779.png') center/cover no-repeat  !important;
  margin-top: 0px;
  margin-bottom: 3px;
  padding: 6px 0px !important; 
  border-radius: 0px !important;
  width: 100% !important; 
  border: 1px solid transparent !important; 
  border-image: url('https://iili.io/fhaBulp.md.png') 30 stretch !important; 
  border-image-slice: 10 !important;
  border-image-repeat: stretch !important; 
  outline: 0px solid #000 !important;
    max-width: 1000px;
    min-height: 0px !important;
    box-shadow: 
  inset 0px 0px 0px rgba(255, 255, 255, 0.9),
  0px 0px 0px rgba(225,232, 164, 0.8);
}

#send_textarea {
  resize: none; 
}

/* 输入框背景色*/
textarea {
    background: 
        radial-gradient(circle at center, #f7f6f4),
        url('无') !important;
    background-size: contain !important;
    background-position: center !important;
    background-repeat: no-repeat !important;
}

/* 输入框位置*/
#form_sheld {
  margin: 0 auto -10px auto !important; 
  transform: translateY(-20px); 
}

/* 头像位置 */
.mesAvatarWrapper {
    position: absolute !important;
    top: -4px !important; /*上下🫐 */
    left: 41.8% !important; /*左右🫐 */
    transform: translateX(-50%) !important;
    z-index: 2 !important;
    margin: 0 !important;.

}
/* 头像大小 */
.mesAvatarWrapper .avatar {
  width: 70px !important;/*宽度🫐 */
  height: 110px !important;/*高度🫐 */
  border-radius: 50% !important;
transform: rotate(-12deg) !important;
box-shadow: 0 0 0px rgba(198, 208, 113, 1) !important;
}

.mesAvatarWrapper .avatar img {
  width: 100% !important;
  height: 100% !important;
  border-radius: 50% !important;
  object-fit: cover !important;
  display: block !important;

}

/* 头像贴图 */
.mesAvatarWrapper::before {
  content: "";
  position: absolute;
  background-image: url('无');
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  width: 50px;
  height: 50px;
  top: 110px;
  left: 72%;
  transform: translateX(-50%);
  z-index: 3;
  pointer-events: none;
}

.mesAvatarWrapper .avatar img {
  box-shadow: none !important;
}

q {
  background: rgba(127,141, 147, 0.1) !important;  
  padding: px 1px !important;
  border-radius: 0px !important;
  font-style: normal !important; 
  box-shadow: 0px 0px 0px rgba(245, 166, 184, 0.5) !important;
  margin: 10px 2px !important; 
  box-decoration-break: clone !important;
  -webkit-box-decoration-break: clone !important;

border-left: 2px solid rgba(131,152, 162, 0.5) !important;
border-right: 2px solid rgba(131,152, 162, 0.5) !important;
}

/* 斜体 */
.mes[is_user="false"] .mes_text i,
.mes[is_user="false"] .mes_text em {
    background: #f7f6f4 !important;  
  padding: 2px 5px !important;
  border-radius: 0px !important;
  font-style: normal !important; 
  box-shadow: 
  inset 0px 0px 0px rgba(230, 239, 182, 0.9),
  0px 2px 3px rgba(161, 177, 181, 0.6);
  border: 0.7px solid #a1b1b5 !important;
outline: 1px solid #f7f6f4 !important;
  box-decoration-break: clone !important;
  -webkit-box-decoration-break: clone !important;
position: relative; 
}

/* 添加前缀和后缀 */
.mes[is_user="false"] .mes_text i::before,
.mes[is_user="false"] .mes_text em::before {
    content: " ◎" !important;
font-size: 1em;
}

.mes[is_user="false"] .mes_text i::after,
.mes[is_user="false"] .mes_text em::after {
    content: "◎" !important;
font-size: 1em;
}

/* 代码块 */
code, .hljs {
  position: relative;
  background: #f7f6f4 !important;  
  padding: 2px 5px !important;
  border-radius: 0px !important;
  font-style: normal !important; 
  box-shadow: 
  inset 0px 0px 0px rgba(230, 239, 182, 0.9),
  0px 2px 3px rgba(161, 177, 181, 0.6);
  border: 0.7px solid #a1b1b5 !important;
outline: 1px solid #f7f6f4 !important;
color: #AAB2B3 !important;
}

/* 时间戳 */
.timestamp {
    position: absolute !important;
    top: 43px !important;
    right: 90px !important;
    color: #5b5b5b !important;
    font-size: 9px !important;
    z-index: 999 !important;
letter-spacing: 1px;
}

.timestamp::before {
    content: "" !important;
    margin-right: 0px;
  color: #949494;
  display: inline !important; 
  vertical-align: middle;
  position: relative;
  top: -1px;
}

.mes_block {
    position: relative !important;
    z-index: 999 !important; 
    isolation: isolate; 
}

.mes, .mes_block {
    overflow: visible !important;
}

/* 名字位置 */
.mes_block .ch_name {
  position: absolute !important;
  top:109px;/*上下🫐 */
  left: 156px;/*左右🫐 */
  z-index: 9999; 
  color: #AAB2B3 !important;
  font-size: 0.9em;
  font-weight: 0!important;

}


/* 添加后缀 */
.mes_block .ch_name::after {
  content: ""; /* 后缀文本 */
  margin-left: 20px;
  color: #949494;
  display: inline !important; /* 改为inline使其与名字在同一行 */
  vertical-align: middle;
  position: relative;
  top: -1px;
  left: -80px !important;
}

/* 楼层 */
.mesIDDisplay {
    position: absolute !important;
    top: 124px !important;/*上下🫐 */
    left: 170px !important;/*左右🫐 */
    display: flex !important;
    font-size: 0.75em!important;
    z-index: 888 !important;
    color: #878D8E;
    font-weight: 500 !important;
    white-space: nowrap !important;
}

.mesIDDisplay::before {
    content: "";
    margin-right: 0px;
    color: #949494;
    display: flex !important;
    vertical-align: middle;
    position: relative;
    top: 0.2px;
}


/* 计时器 */
.mes .mes_timer {
    position: absolute !important;
    top: 80px !important;  /*上下🫐 */
    left: 100px !important;  /*左右🫐 */
    display: flex !important;
    font-size: 0.7em;
    z-index: 999 !important;
    font-weight: 600;
    color: #C4CED0;
    white-space: nowrap !important;
opacity: 1;
}

.mes .mes_timer::before {
    content: "";
    margin-right: 0px;
    color: #949494;
    display: inline-block;
    vertical-align: middle;
    position: relative;
    top: 0.2px;
}
/* 词符 */
.mes .tokenCounterDisplay {
    position: absolute !important;
    top: 90px !important;/*上下🫐 */
    left: 110px !important;  /*左右🫐 */
    display: flex !important;
    font-size: 0.7em;
    z-index: 888 !important;
    opacity: 1;
    color: #C4CED0;
font-weight: 600;

}

.mes .tokenCounterDisplay::before {
    content: "";
    margin-right: 0px;
    color: #AEAEAE;
    display: inline-block;
    vertical-align: middle;
    position: relative;
    top: 0.2px;
    white-space: nowrap !important;
}


/* 允许消息块和按钮容器溢出显示 */
.mes, 
.mes_block, 
.mes_buttons, 
.extraMesButtons {
    overflow: visible !important;
}

/* 编辑按钮位置 */
.mes_buttons {
    position: absolute !important;
    top: 19px !important;/*上下🫐 */
    right: -125px !important;/*左右🫐 */
    z-index: 999 !important;
    flex-direction: row !important; 
}

/* 编辑状态时按钮位置 */
.mes_edit_buttons {
    position: relative !important;
    top: -50px !important;/*上下🫐 */
    left: -120px !important;/*左右🫐 */
    margin-bottom: -20px !important;
    z-index: 100 !important;
}
/*省略号菜单位置 */
.extraMesButtons {
  position: absolute;
  top: 0px;
  right: 20px;

}

/*省略号菜单图标颜色 代码源@易碎蝶老师 */
.mes_button, .extraMesButtons>div {
cursor: pointer;
    transition: opacity 0.2s ease-in-out;
    filter: drop-shadow(0px 0px 0px #AB9B74) !important;
    /* ⭕设置省略号菜单颜色 */
    color: #7F8D93 !important;
opacity: 1 !important; 
}

/* 编辑的省略号图标*/
.fa-ellipsis-h, 
.fa-ellipsis {
    background: url('https://iili.io/fh7bzuI.md.png') center/contain no-repeat !important;
    width: 15px !important;   
    height: 15px !important;  
    color: transparent !important; 
z-index: 999 !important;
    opacity: 1 !important
}

/*替换编辑图标*/
 .fa-pencil {
    background: url('https://iili.io/fh7bzuI.md.png') center/contain no-repeat !important;
    width: 15px !important;
    height: 15px !important;
    color: transparent !important;
z-index: 999 !important;
    opacity: 1 !important
}

/* 导航栏 */
#top-bar::after {
    content: "";
    position: fixed;
    top: var(--topBar-height, 0px); 
    left: 0px;
    width: 100%;
    height: 100px;
    background: url('https://i.postimg.cc/d0SKcVFn/IMG-2774.png') center/cover no-repeat;
    z-index: 99;
}

#top-bar::before {
    content: "";
    position: fixed;
    top: calc(var(--topBar-height, -15px) + 40px); 
    left: 310px;
    width: 12%;
    height: 80px; 
    background: url('无') center/cover no-repeat;
    z-index: 999; 
}

#top-settings-holder .drawer {
    flex: 1; 

}
#top-settings-holder .drawer-icon {
    transform: scale(0.6); 
    background: linear-gradient(1deg, #33, #fff) !important;
    -webkit-background-clip: text !important;
    background-clip: text !important;
    color: transparent !important;
opacity: 0.3 !important
}

/* 预设 */
/* 背景 */
#completion_prompt_manager #completion_prompt_manager_list {
  background: rgba(255, 255, 255, 0);
  border-radius: 10px !important;
  border: 0px solid #fff !important;
  box-shadow: 
  inset 0px 0px 5px rgba(255, 255, 255, 0),
  0px 0px 3px rgba(129, 150, 180, 0);
  padding: 8px !important;
  transition: all 0.3s ease !important; 
  position: relative !important;
  overflow: hidden !important;
transform: translateX(0px);
}

#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name, #completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name .prompt-manager-inspect-action {
    color: var(--customThemeColor-purple);
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt_disabled {
  opacity: 1;
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt {
  background-color: #FCFCFC !important; 
  color: #7F8D93 !important; 
  box-shadow: 
  inset 0px 0px 0px rgba(230, 239, 182, 0.9),
  0px 2px 3px rgba(161, 177, 181, 0.6); 
  border: 0.7px solid #a1b1b5 !important;
outline: 1px solid #f7f6f4 !important;
  border-radius: 0px !important; 
  padding: 1px 1px !important; 
  margin: 5px 5px !important; 
}

#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled {
  background-color: #EAEBEB !important; 
  color: #7F8D93 !important; 
  box-shadow: 
  inset 2px 0px 0px rgba(255, 255, 255, 0),
  inset 0px 0px 5px rgba(255, 255, 255, 0),
  0px 0px 0px rgba(129, 150, 180, 0); 
  border: 0px solid #fff !important;
outline: 0px solid #262626 !important; 
  border-radius: 0px !important;
  margin: 8px 5px !important;
  opacity: 1 !important; 
}

/* 条目已开启颜色 代码源@hy */
.completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) .fa-toggle-on {
    color: rgba(161, 177, 181, 1) !important; 
    text-shadow: 0 0 0px rgba(0, 0, 0, 1) !important;
opacity: 1 !important;
}

/*菜单按钮*/
.menu_button {
  background: #f0efed !important;  
  border-radius: 0px !important; 
  box-shadow: 
  inset 0px 0px 0px rgba(230, 239, 182, 0.9),
  0px 2px 3px rgba(161, 177, 181, 0.6);
  border: 0.7px solid #a1b1b5 !important;
outline: 1px solid #f7f6f4 !important; 
  padding: 1px 4px !important; 
  color: #7F8D93 !important;
  opacity: 1 !important
}

/* 下拉框 */
select {
  background: transparent;
  border: none;
  border-bottom: 1px dashed #A5B9C2;
  border-radius: 0;
  color: #A5B9C2;
  padding: 3px 1px;
  width: 100%;
  outline: none;
}

select, 
select option {
  color: #7F8D93 !important;
}

/* 勾选框 */
input[type='checkbox'] {
  background-color: #f0efed !important;
  border: 1.5px solid #E6E6E6 !important;
  border-radius: 0px !important;
  appearance: none !important; 
  -webkit-appearance: none !important;
  width: 13px !important;
  height: 13px !important;
  cursor: pointer !important;
  position: relative !important;
  transition: all 0.3s ease !important;
  top: 3px !important;
box-shadow: 
  inset 2px 2px 6px rgba(102,123, 127, 0.6),
  0px 2px 3px rgba(102,123, 127, 0.5); 
}

/* 选中 */
input[type='checkbox']:checked {
  background-color: #A1B1B5 !important;
  border-color: #E6E6E6 !important;
  box-shadow: 
    inset 2px 2px 8px rgba(102,123, 127, 0.9),             
    0px 2px 3px rgba(102,123, 127, 0.5);
}

/* 气泡内的勾选框 */
.mes input[type="checkbox"] {
    top: 55px !important;  
    left: 30px !important; 
    z-index: 9999 !important; 
    opacity: 1 !important;
    float: none !important;
    margin: 0 !important;
    pointer-events: auto !important; 

    width: 15px !important;
    height: 15px !important;
    background-color: #f2f7fd !important;
    border: 1.5px solid #fff !important; 
    border-radius: 25% !important; 
}

/* 选中时 */
.mes input[type="checkbox"]:checked {
    background-color: #A96D6D !important;
    border-color: #fff !important;
    box-shadow: 0 0 0px rgba(226, 198, 209, 1) !important;
}

.mes_select_box, .mes_checkbox {
    overflow: visible !important;
    z-index: 9999 !important;
}

/* 标题 */
.inline-drawer-header,
#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
#user-settings-block h4,
.standoutHeader {
  background-size: 100%;
  overflow: visible !important;
  background-image: url("https://i.postimg.cc/TYg6ZxhS/IMG-2779.png");
  border: 1.5px solid transparent !important; 
  border-image: url('https://iili.io/fhaBulp.md.png') 30 stretch !important; 
  border-image-slice: 10 !important;
  border-image-repeat: stretch !important;
  box-shadow: 
  inset 0px 0px 8px rgba(82, 105, 114, 0.8),
  inset 0px 0px 5px rgba(82, 105, 114, 0.8),
  0px 2px 2px rgba(82, 105, 114, 0.3); 
  border-radius: 0px;
  transition: all 0.2s cubic-bezier(0.34, 1.56, 0.64, 1);
  position: relative;
  overflow: hidden;
  padding: 2px 15px !important;
  color: #E6E6E6;
}

/*输入文本框*/
textarea {
  box-shadow: inset 0px 0px 2px rgba(97, 118, 124, 0.8) !important;
  border: 0px solid #fff!important;
  border-radius: 0px !important; 
  color: #878D8E !important; 
}
/*文本选中时颜色*/
::selection {
  background-color: #无;
  color: #无;
}

/*加载更多消息 代码源@易碎蝶老师*/
#show_more_messages {
    text-align: center;
    margin: 65px auto;
    font-weight: 500;
    order: -1;
    cursor: pointer;
    padding: 0.5em 1em;
    background: url('底色背景图') center/cover, #f7f6f4;
    width: fit-content;
    border-radius: 2px;
    border: 0.7px solid #a1b1b5 !important;
outline: 1px solid #f7f6f4 !important;
    box-shadow: 
  inset 0px 0px 0px rgba(230, 239, 182, 0.9),
  0px 2px 3px rgba(161, 177, 181, 0.6);
    color: transparent;
    position: relative;
    display: block; 
    z-index: 999 !important;
    min-height: 20px; 
}

#show_more_messages::after {
    content: "独自青青◎君始知";
    color: #A1B1B5;
    position: absolute;
    left: 0;
    right: 0;
    top: 0;
    bottom: 0;
